import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt', 'html'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def compute_hash(filepath):
    """Compute SHA256 for audit logging"""
    h = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            h.update(chunk)
    return h.hexdigest()

def sanitize_filename(filename):
    """Remove path traversal attempts and null bytes"""
    filename = filename.replace('\x00', '')
    filename = filename.replace('..', '')
    filename = secure_filename(filename)
    return filename

@app.route('/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    safe_name = sanitize_filename(file.filename)
    if not safe_name:
        return jsonify({'error': 'Invalid filename'}), 400

    os.makedirs(UPLOAD_DIR, exist_ok=True)
    input_path = os.path.join(UPLOAD_DIR, safe_name)
    file.save(input_path)

    file_hash = compute_hash(input_path)
    app.logger.info(f'Processing file {safe_name} (sha256: {file_hash})')

    # Convert to PDF using LibreOffice in headless mode
    output_format = request.form.get('format', 'pdf')

    # Build conversion command
    cmd = f'libreoffice --headless --convert-to {output_format} --outdir {UPLOAD_DIR} {input_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            timeout=30,
            capture_output=True,
            text=True
        )

        if result.returncode != 0:
            app.logger.error(f'Conversion failed: {result.stderr}')
            return jsonify({'error': 'Conversion failed'}), 500

        # Determine output filename
        base_name = os.path.splitext(safe_name)[0]
        output_path = os.path.join(UPLOAD_DIR, f'{base_name}.{output_format}')

        if not os.path.exists(output_path):
            return jsonify({'error': 'Output file not generated'}), 500

        return send_file(
            output_path,
            as_attachment=True,
            download_name=f'{base_name}.{output_format}'
        )
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.1.0'})

@app.route('/supported-formats', methods=['GET'])
def supported_formats():
    return jsonify({
        'input': list(ALLOWED_EXTENSIONS),
        'output': ['pdf', 'docx', 'odt', 'html', 'txt']
    })

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
